    to_delete = set(map(int, input().split()))

    # Find the longest common prefix and suffix
    common_prefix = ""
    common_suffix = ""
    min_len = min(len(f) for f in files)

    for i in range(min_len):
        chars = set(f[i] for j, f in enumerate(files) if j + 1 in to_delete)
        if len(chars) == 1:
            common_prefix += chars.pop()
        else:
            break

    for i in range(1, min_len + 1):
        chars = set(f[-i] for j, f in enumerate(files) if j + 1 in to_delete)
        if len(chars) == 1:
            common_suffix = chars.pop() + common_suffix
        else:
            break

    # Find the middle pattern
    middle_pattern = []
    for i in range(len(common_prefix), len(files[0]) - len(common_suffix)):
